def safe_divide(num, den):
    def _div(a, b):
        with np.errstate(divide="ignore", invalid="ignore"):
            return np.divide(a, b)

    out = xr.apply_ufunc(
        _div,
        num, den,
        dask="parallelized",
        output_dtypes=[np.float64],
    )
    return out.where(den > 0)

def safe_sqrt_inv(den):
    inv = safe_divide(1.0, den)
    return xr.apply_ufunc(
        np.sqrt,
        inv,
        dask="parallelized",
        output_dtypes=[np.float64],
    )
